insert into public.guia_bebidas (slug, categoria, subgrupo, orden, nombre, precio, meta, datos, en_sala, minima_intervencion, a_confirmar) values
  ('kido-junmai-ginjo', 'sake', 'All Round · versátiles y equilibrados', 1, 'Kido Junmai Ginjo', '12 € copa / 20 € jarra', 'Heiwa Shuzo · Kainan (Wakayama) · junmai ginjo', '["La marca se escribe 紀土 y se lee \"Kid\": viene de *Kishū no fūdo*, el terruño de Kishū, nombre antiguo de la región.", "Yamada Nishiki y Gohyakumangoku pulidos en torno al 50-55 %. Agua subterránea muy blanda, que da textura suave.", "Fresco, frutal y equilibrado, con una acidez fina de fondo."]'::jsonb, 'el sake de bienvenida; acompaña casi todo el menú sin tapar la cocina.', false, false),
  ('niida-shizenshu-ginjo', 'sake', 'All Round · versátiles y equilibrados', 2, 'Niida Shizenshu Ginjo', '14 € copa / 24 € jarra', 'Niida Honke · Kōriyama (Fukushima) · junmai ginjo kimoto', '["Bodega familiar desde 1711, con 18 generaciones al frente. En 1967 lanzó el primer \"sake natural\" de Japón.", "Solo arroz cultivado sin pesticidas ni fertilizantes químicos; sus campos propios tienen certificación orgánica. Desde 2011 todo es junmai y desde 2015 todo es kimoto.", "Sin levadura añadida: fermenta con la de la bodega. Pulido al 60 %, 15 % de alcohol.", "Notas lácticas, de champiñón y manzana asada, con acidez viva."]'::jsonb, 'para quien valora lo natural y la mínima intervención.', false, false),
  ('nichi-nichi', 'sake', 'All Round · versátiles y equilibrados', 3, 'Nichi-Nichi (日日)', null, 'Nichinichi Jōzō · Fushimi (Kioto) · kimoto, sin categoría declarada', '["Bodega fundada en diciembre de 2021 por Hidehiko Matsumoto, antes tōji de la bodega familiar Matsumoto Shuzo. El nombre viene del dicho zen \"cada día es un buen día\".", "Yamada Nishiki de Tōjō (Hyōgo), de campos propios y agricultores por contrato. Solo publica los ingredientes: quiere que se juzgue el arroz y el lugar.", "Como no declara el pulido, la etiqueta no lleva categoría. Es solo arroz y koji.", "Aroma suave (pera, uva moscatel), ligera aguja natural, acidez fresca y en torno a 12-13 % de alcohol."]'::jsonb, 'el ejemplo del sake moderno de autor, con poco alcohol y mucha precisión.', false, false),
  ('tedorigawa-tokujo-arabashiri', 'sake', 'Fruity · afrutados y aromáticos', 4, 'Tedorigawa Tokujo Arabashiri', null, 'Yoshida Shuzoten · Hakusan (Ishikawa) · junmai daiginjo nama genshu', '["Bodega fundada en 1870; la marca toma el nombre del río Tedori.", "Yamada Nishiki de Hyōgo pulido al 45 %, 15 % de alcohol. Se embotella desde el *arabashiri* (lo que fluye antes de apretar la prensa) hasta el *nakagumi* (la fracción media).", "Es sin pasteurizar: **siempre en cámara**.", "Jazmín y manzana; boca elegante, textura cremosa y final fresco."]'::jsonb, 'sirve para explicar que de una misma prensa salen sakes distintos según el momento.', false, false),
  ('afs', 'sake', 'Funky-Natural · complejos y salvajes', 5, 'AFS', '15 € copa / 28 € jarra', 'Kidoizumi Shuzo · Isumi (Chiba) · junmai yamahai muroka nama genshu', '["Bodega pionera del sake sin aditivos; es la única de Japón que trabaja solo con yamahai \"caliente\".", "Método propio: pie de cuba yamahai a alta temperatura y fermentación en una sola tanda. Resultado muy dulce y muy ácido a la vez, con 13-14 % de alcohol.", "AFS son las iniciales de sus tres creadores: Adachi, Furukawa y Shoji."]'::jsonb, 'para paladares curiosos; recuerda a un blanco dulce con mucha acidez. Siempre en cámara.', false, false),
  ('natsu-no-omoide', 'sake', 'Funky-Natural · complejos y salvajes', 6, 'Natsu no Omoide', '15 € copa / 28 € jarra', 'Mukai Shuzo · Ine (Kioto, costa del Mar de Japón) · junmai de koji blanco', '["Bodega de 1754 en un pueblo de pescadores con casas sobre el agua. La tōji es Kuniko Mukai, desde 1999 la primera mujer tōji de la prefectura de Kioto.", "El nombre significa \"Recuerdos de verano\". Está hecho con koji blanco, el del shochu, que produce ácido cítrico: de ahí su acidez de limón.", "La nuestra es la reedición moderna, no la partida añeja de 2000. Pulido al 70 %, 14 % de alcohol y nihonshudo en torno a −30: claramente dulce.", "Agridulce y jugoso, entre cítrico y uva madura."]'::jsonb, 'buen ejemplo de cómo el tipo de koji cambia el sake. La bodega lo sugiere frío, con hielo o con soda.', false, false),
  ('ine-mankai', 'sake', 'Funky-Natural · complejos y salvajes', 7, 'Ine Mankai', '19 € copa / 38 € jarra', 'Mukai Shuzo · Ine (Kioto) · junmai de arroz antiguo', '["Lleva arroz antiguo pigmentado, variedad Murasaki-komachi, además de arroz blanco: de ahí su color rosado natural. En Japón se vende como \"sake de arroz rojo\".", "Es la primera creación propia de Kuniko Mukai, nacida de una idea de sus años de universidad. Se sirvió en el G20 de Osaka de 2019.", "14 % de alcohol. Muy dulce y muy ácido: agridulce, a arándano y cereza."]'::jsonb, 'impacto visual; acompaña sabores potentes, salsas e incluso postres.', false, false),
  ('senkin-nature', 'sake', 'Funky-Natural · complejos y salvajes', 8, 'Senkin Nature', null, 'Senkin · Sakura (Tochigi) · kimoto, sin categoría declarada', '["La línea más \"natural\" de la casa: arroz antiguo Kame no O de cultivo ecológico, de campos que comparten la veta de agua de la bodega, pulido solo al 90 %.", "Kimoto, levadura de la bodega y fermentación en tinas de madera; solo arroz, koji y agua.", "Crema, albaricoque y manzana verde; algo de aguja, acidez marcada y umami. 13 % de alcohol."]'::jsonb, 'junto al Senkin Modern muestra dos caras de una misma bodega.', false, false),
  ('daigo-no-shizuku', 'sake', 'Funky-Natural · complejos y salvajes', 9, 'Daigo no Shizuku', null, 'Terada Honke · Kōzaki (Chiba) · junmai bodaimoto, nama genshu sin filtrar', '["Bodega de más de 340 años, referente del sake natural.", "Reproduce el sake de los templos medievales con *bodaimoto*. Arroz sin pesticidas pulido al 90-93 % y levadura de la bodega.", "Cambia con cada lote: alcohol entre 6 y 17 %, muy dulce y muy ácido. Recuerda a un vino de frutas o a un hidromiel.", "**Siempre en cámara y siempre de pie**; puede refermentar en botella, así que se abre con cuidado."]'::jsonb, 'el estilo más antiguo de la carta, para contar cómo era el sake hace siglos.', false, false),
  ('kido-daiginjo-50', 'sake', 'Clean & Elegant · finos y sofisticados', 10, 'Kido Daiginjo 50', '15 € copa / 28 € jarra', 'Heiwa Shuzo · Kainan (Wakayama) · junmai daiginjo', '["Yamada Nishiki al 100 %, pulido al 50 %.", "Fruta limpia, textura sedosa y final seco y nítido."]'::jsonb, 'frente al Kido Junmai Ginjo, lo que más cambia es el arroz (todo Yamada Nishiki), no tanto el pulido.', false, false),
  ('kido-daiginjo-40', 'sake', 'Clean & Elegant · finos y sofisticados', 11, 'Kido Daiginjo 40', null, 'Heiwa Shuzo · Kainan (Wakayama) · junmai daiginjo', '["La versión más pulida: queda el 40 % del grano de Yamada Nishiki.", "Al pulir más se elimina más proteína y grasa: aroma más fino y floral, boca más limpia y ligera."]'::jsonb, 'con el Daiginjo 50 enseña en dos copas qué cambia al pulir más. El salto de pulido real es de 50 a 40.', false, false),
  ('nabeshima-50', 'sake', 'Clean & Elegant · finos y sofisticados', 12, 'Nabeshima 50', '16 € copa / 32 € jarra', 'Fukuchiyo Shuzo · Kashima (Saga) · junmai ginjo Yamada Nishiki, la "etiqueta morada"', '["Pequeña bodega junto al mar de Ariake. La marca nació en 1998 y lleva el nombre del clan que gobernó Saga unos 300 años.", "Marca de culto desde que su Daiginjo fue Champion Sake en el International Wine Challenge de 2011.", "Yamada Nishiki pulido al 50 %, nivel de daiginjo aunque la bodega lo etiquete como junmai ginjo. 16 % de alcohol y, a veces, ligera aguja.", "Afrutado y aterciopelado, con acidez que equilibra el dulzor."]'::jsonb, 'la categoría marca un mínimo, no un techo: este ginjo está pulido como un daiginjo.', false, false),
  ('senkin-modern', 'sake', 'Clean & Elegant · finos y sofisticados', 13, 'Senkin Modern', '16 € copa / 32 € jarra', 'Senkin · Sakura (Tochigi) · kimoto muroka genshu, sin categoría declarada', '["Dos hermanos de la undécima generación: Kazuki Usui, exsumiller, y Masato, el tōji. Trabajan como un *domaine*: el arroz crece sobre la misma veta de agua con la que elaboran.", "Yamada Nishiki con koji al 50 % y resto al 60 %: por pulido equivale a un junmai ginjo, no a un daiginjo. 13-14 % de alcohol.", "La casa busca acidez de vino blanco. Manzana, melocotón, cítricos; jugoso y brillante."]'::jsonb, 'el puente para quien bebe vino blanco. En copa de vino.', false, false),
  ('otora', 'sake', 'Dry · secos y nítidos', 14, 'Otora (大虎)', null, 'Chiyokotobuki Toraya · Sagae (Yamagata) · junmai muy seco', '["*Ōtora* significa \"gran tigre\"; la bodega se llama Toraya, \"casa del tigre\".", "Arroz pulido al 70 %, 15 % de alcohol y nihonshudo +10: muy seco.", "Aroma discreto a cereal, boca limpia y final cortante."]'::jsonb, 'para quien pide "algo seco"; limpia entre piezas y admite templado.', false, false),
  ('ginrei-gassan-junmai-daiginjo', 'sake', 'Dry · secos y nítidos', 15, 'Ginrei Gassan Junmai Daiginjo', null, 'Gassan Shuzo · Sagae (Yamagata) · junmai daiginjo, edición limitada', '["Bodega fundada en 1972 al pie del monte Gassan, zona de nevadas muy intensas.", "Agua subterránea del Gassan, incluida entre las \"100 aguas más famosas de Japón\". Estilo limpio, ligero y seco.", "Arroz pulido al 50 % y 15 % de alcohol; lleva el sello de un trofeo del International Wine Challenge. *A confirmar con la botella: existe otra cuvée, 100 % Yamada Nishiki, pulida al 45 %.*"]'::jsonb, 'el seco elegante frente al seco rústico del Otora; los dos son de la misma ciudad.', false, true),
  ('seafood-fukucho', 'sake', 'Dry · secos y nítidos', 16, 'Seafood (Fukuchō)', null, 'Imada Shuzo Honten · Akitsu (Hiroshima) · junmai de koji blanco', '["Bodega de 1868 junto al mar interior de Seto. Su dueña y tōji, Miho Imada, figuró en la lista 100 Women de la BBC en 2020 y recuperó el arroz antiguo Hattansō.", "Nació cuando un chef de Tokyo le pidió un sake para ostras. Usa koji blanco, que aporta ácido cítrico.", "Pulido al 70 %, 13 % de alcohol, nihonshudo −3 y acidez 3,5: más ácido que seco.", "Ligero y cítrico, como un blanco para marisco."]'::jsonb, 'con ostras, marisco y piezas grasas. Si alguien pide "seco" a secas, mejor el Otora.', false, false),
  ('hanatomoe-junmai-yamahai', 'sake', 'Rustic · tradicionales y estructurados', 17, 'Hanatomoe Junmai Yamahai', '13 € copa / 25 € jarra', 'Miyoshino Jōzō · Yoshino (Nara) · junmai yamahai', '["Bodega de 1912 en la zona de los \"mil cerezos\" de Nara, cuna histórica del sake.", "Sin levadura añadida. El tōji, Teruaki Hashimoto, sostiene que \"el aire hace el sake\".", "Acidez alta, mucho cuerpo y final lácteo."]'::jsonb, 'aliado del umami (setas, carnes, salsas). Admite templado.', false, false),
  ('biden', 'sake', 'Añejo · koshu', 18, 'Biden', '14 € copa / 24 € jarra', 'Mii no Kotobuki · Tachiarai (Fukuoka) · junmai yamahai añejo', '["Yamada Nishiki de Itoshima fermentado con yamahai y añejado a temperatura ambiente.", "La partida actual ya no es la añada 1999: es una mezcla de añadas 1994, 2015 y 2018. 16 % de alcohol.", "Miel, caramelo, pasas y frutos secos tostados; recuerda a un jerez."]'::jsonb, 'para el final de la cena y para quien disfruta de jereces viejos. A temperatura ambiente o templado.', false, false),
  ('akishika-yamahai-moto-shibori-2003', 'sake', 'Añejo · koshu', 19, 'Akishika Yamahai Moto-shibori 2003', '15 € copa / 28 € jarra', 'Akishika Shuzo · Nose (Osaka) · junmai yamahai, prensado del pie de cuba, añejo', '["Bodega de 1886 en el extremo norte de Osaka. Cultiva buena parte de su arroz y desde 2003 solo elabora junmai.", "*Moto-shibori*: en lugar de completar la elaboración, se prensó directamente el pie de cuba, en marzo de 2003.", "Arroz propio pulido al 70 %, 10 % de alcohol, nihonshudo −63 y acidez 9,0; un sake habitual ronda 1,5.", "Más de veinte años de guarda: color ámbar, dulzor y acidez muy intensos, caramelo y fruta seca."]'::jsonb, 'copa de meditación y la mejor forma de enseñar qué es un pie de cuba.', false, false),
  ('chokyu-1997', 'sake', 'Añejo · koshu', 20, 'Chokyu 1997', null, 'Nakano BC · Kainan (Wakayama) · junmai kijoshu añejo, botella de 300 ml', '["De la misma ciudad que Heiwa Shuzo. La empresa empezó con salsa de soja; \"BC\" significa *Biochemical Creation*. También hace umeshu.", "*Kijoshu* elaborado una sola vez, en 1997, y añejado desde entonces. 16 % de alcohol.", "Agridulce, con caramelo profundo y notas terrosas y de chocolate."]'::jsonb, 'aperitivo, digestivo o con postre, a temperatura ambiente.', false, false),
  ('2018-recaredo-serral-del-vell', 'espumoso', 'Del inicio de la carta a los 100 €', 21, '2018 Recaredo Serral del Vell', '72 €', 'Corpinnat · Alt Penedès · xarel·lo y macabeu · brut nature', '["Recaredo es la referencia histórica del espumoso catalán de larga crianza. Todo lo que hace es de añada, brut nature y de viña propia en biodinámica.", "Serral del Vell es una finca concreta de suelos muy calcáreos. Cría en botella con tapón de corcho (no chapa) y se degüella a mano.", "Perfil: seco, hinojo y hierbas mediterráneas, cítrico maduro, final salino y algo amargo."]'::jsonb, 'la entrada más sensata a la burbuja de la carta; seco de verdad, acompaña todo el menú.', false, false),
  ('2016-llopart-ex-vite-brut-ed-25-aniversari', 'espumoso', 'Del inicio de la carta a los 100 €', 22, '2016 Llopart Ex Vite Brut, Ed. 25 Aniversari', '85 €', 'Corpinnat · Subirats · 60 % xarel·lo, 40 % macabeu · brut', '["La cuvée alta de Llopart, de viñas viejas de montaña de la propia finca; esta edición celebra su 25.ª añada.", "Más de 100 meses sobre lías: es el espumoso de crianza más larga de la carta entre los que no son Champagne.", "Perfil: maduro y cremoso, manzana asada, fruto seco, panadería; burbuja muy integrada."]'::jsonb, 'para quien disfruta la burbuja evolucionada. Va muy bien con piezas de más grasa y con anago.', false, false),
  ('nv-gonet-medeville-blanc-de-noirs-1er-cru', 'espumoso', 'Del inicio de la carta a los 100 €', 23, 'NV Gonet-Médeville Blanc de Noirs 1er Cru', '88 €', 'Champagne · Bisseuil (Grande Vallée de la Marne) · pinot noir', '["Pequeño domaine de Xavier Gonet y Julie Médeville (ella, de la familia de Château Gilette en Sauternes).", "Pinot noir de Bisseuil, pueblo premier cru. Estilo limpio, de dosage bajo.", "Perfil: fruta roja fresca, cítrico, más volumen en boca que un blanc de blancs."]'::jsonb, 'el blanc de noirs accesible; útil cuando piden champagne "con algo más de cuerpo".', false, false),
  ('nv-roger-coulon-heri-hodie', 'espumoso', 'Del inicio de la carta a los 100 €', 24, 'NV Roger Coulon Heri Hodie', '90 €', 'Champagne · Vrigny (Montagne de Reims) · 1er cru · extra brut', '["Familia de viticultores en Vrigny desde 1806; hoy en ecológico y agroforestería. Fermentan con levaduras propias y no clarifican ni filtran.", "*Heri Hodie* = \"ayer, hoy\" en latín: sale de una reserva perpetua iniciada en 1995.", "La composición cambió con los años (hubo tiradas con las tres uvas); las actuales se presentan como 100 % meunier. *Confirmar en la contraetiqueta de la tirada que tengamos.*", "Perfil: fruta amarilla madura, especia dulce, textura amplia, final fresco."]'::jsonb, 'buen ejemplo para explicar qué es una reserva perpetua.', false, true),
  ('nv-m-marcoult-b-de-barbonne-extra-brut', 'espumoso', 'Del inicio de la carta a los 100 €', 25, 'NV M. Marcoult B. de Barbonne Extra Brut', '95 €', 'Champagne · Barbonne-Fayel (Côte de Sézanne) · chardonnay · extra brut', '["Domaine familiar fundado en 1967, hoy en tercera generación. Son de los pocos que vinifican y embotellan lo propio en la Côte de Sézanne.", "Blanc de blancs del pueblo de Barbonne: chardonnay algo más maduro que el de la Côte des Blancs, pero con final salino.", "Perfil: fruta blanca, cítrico, tiza, amargor fino al final."]'::jsonb, 'blanc de blancs directo y salino; muy bueno con pescado blanco y mariscos.', false, false),
  ('nv-marguet-shaman-rose-grand-cru', 'espumoso', 'Del inicio de la carta a los 100 €', 26, 'NV Marguet Shaman Rosé Grand Cru', '100 €', 'Champagne · Ambonnay y Bouzy · chardonnay y pinot noir · brut nature · mínima intervención', '["Benoît Marguet trabaja en biodinámica, labra con caballos y elabora sin sulfuroso añadido y sin dosage.", "*Shaman* es su cuvée de entrada; el número que acompaña al nombre en la etiqueta es el año de la cosecha base.", "Es un rosado de mezcla (base de blanco con una parte de tinto de pinot noir). La proporción varía en cada tirada.", "Perfil: fruta roja ácida, piel de naranja, hierbas; muy vinoso y seco."]'::jsonb, 'el único rosado de la carta. Va bien con akami, toro y piezas marinadas.', true, false),
  ('nv-ar-lenoble-dosage-zero-v19', 'espumoso', 'De 110 a 160 €', 27, 'NV AR Lenoble Dosage Zéro V19', '110 €', 'Champagne · Damery (Vallée de la Marne) · pinot noir, meunier y chardonnay · sin dosage', '["Casa familiar e independiente. Guarda parte de sus vinos de reserva en magnum con corcho, lo que les da frescura y complejidad.", "La sigla de la etiqueta identifica la tirada; \"V19\" correspondería a la vendimia base 2019 (*a confirmar*).", "Perfil: seco y recto, fruta blanca, fruto seco suave por las reservas."]'::jsonb, 'para quien pide "lo más seco".', false, true),
  ('nv-charles-heidsieck-brut-reserve', 'espumoso', 'De 110 a 160 €', 28, 'NV Charles Heidsieck Brut Réserve', '110 €', 'Champagne · Reims · pinot noir, chardonnay y meunier · brut', '["La gran casa clásica de la carta. Su sello es una proporción muy alta de vinos de reserva viejos en la mezcla.", "Perfil: el más goloso y tostado del tramo; brioche, fruta de hueso, avellana."]'::jsonb, 'el champagne "de casa grande" para quien quiere un estilo reconocible y redondo. Es el único brut clásico entre tantos extra brut.', false, false),
  ('nv-larmandier-bernier-longitude-blanc-de-blancs-1er-cru', 'espumoso', 'De 110 a 160 €', 29, 'NV Larmandier-Bernier Longitude Blanc de Blancs 1er Cru', '115 €', 'Champagne · Vertus (Côte des Blancs) · chardonnay · extra brut', '["Pierre y Sophie Larmandier, pioneros de la biodinámica en la Côte des Blancs. Fermentan en madera grande con levaduras propias.", "Chardonnay de Vertus, Oger, Avize y Cramant, con una reserva perpetua detrás.", "Perfil: tiza, limón, textura cremosa pero tensa."]'::jsonb, 'el blanc de blancs de referencia de la carta por equilibrio entre tensión y textura.', false, false),
  ('nv-doyard-revolution-blanc-de-blancs-grand-cru', 'espumoso', 'De 110 a 160 €', 30, 'NV Doyard Révolution Blanc de Blancs Grand Cru', '120 €', 'Champagne · Vertus, con viñas grand cru en la Côte des Blancs · chardonnay · sin dosage', '["Yannick y Guillaume Doyard, unas 11 hectáreas trabajadas en ecológico, en parte con caballo y a rendimientos bajos.", "Mezcla de tres cosechas, vinificada mitad en barrica borgoñona usada y mitad en acero.", "Perfil: pera, cítrico, pan recién hecho; seco pero con cuerpo gracias a la madera."]'::jsonb, 'misma línea que Larmandier, un punto más serio y sin azúcar.', false, false),
  ('nv-jacquesson-cuvee-749', 'espumoso', 'De 110 a 160 €', 31, 'NV Jacquesson Cuvée 749', '125 €', 'Champagne · Dizy · chardonnay, pinot noir y meunier · extra brut', '["Jacquesson no busca que su sin añada sepa igual todos los años: cada número (la serie empezó en la 728) es el retrato de una cosecha base distinta.", "La 749 correspondería a la base 2021 (*a confirmar en contraetiqueta*). Fermentación en fudres, uvas de Aÿ, Dizy, Hautvillers, Avize y Oiry.", "Perfil: vinoso, cítrico, toque de madera noble, final largo."]'::jsonb, 'para el cliente que ya conoce champagne y quiere algo con identidad de año.', false, true),
  ('2022-wirth-michel-les-meuniers-de-raoul-extra-brut', 'espumoso', 'De 110 a 160 €', 32, '2022 Wirth Michel Les Meuniers de Raoul Extra Brut', '135 €', 'Champagne · Moussy (Coteaux Sud d''Épernay) · 100 % meunier · extra brut', '["Antonin Michel es nieto de José Michel, uno de los pioneros del meunier serio en Moussy. El domaine lo fundó Raoul Bouché, de ahí el nombre.", "Aunque suele venderse sin añada en etiqueta, es de una sola cosecha.", "Perfil: ciruela fresca, frambuesa, jengibre, especia suave."]'::jsonb, 'la botella para mostrar qué es el meunier solo.', false, false),
  ('nv-hure-freres-memoire', 'espumoso', 'De 110 a 160 €', 33, 'NV Huré Frères Mémoire', '140 €', 'Champagne · Ludes (Montagne de Reims) · pinot noir, meunier y chardonnay · extra brut', '["Sale de una solera iniciada en 1982 y guardada en fudres: cada botella contiene una fracción de todas las cosechas desde entonces.", "Pese a eso no es oxidativo; el dosage es mínimo.", "Perfil: avellana, ciruela, cítrico confitado, con una frescura que sorprende."]'::jsonb, '"cuarenta años en una copa". Muy bueno con piezas curadas o maduradas.', false, false),
  ('2017-bufadors-vinya-del-rascara-brut-nature', 'espumoso', 'De 110 a 160 €', 34, '2017 Bufadors Vinya del Rascarà Brut Nature', '145 €', 'Corpinnat · Sant Sadurní d''Anoia · 100 % xarel·lo · mínima intervención', '["Xarel·lo de una sola parcela sobre caliza pura. Fermenta con levaduras propias, sin sulfitos añadidos y sin dosage.", "Varios años sobre lías y producción mínima: de la 2017 se hicieron 2.185 botellas.", "Perfil: muy pálido, hierbas mediterráneas, ahumado sutil, boca cítrica y vibrante."]'::jsonb, 'el Corpinnat de culto de la carta; se puede presentar al nivel de un buen champagne de viticultor.', true, false),
  ('2016-pierre-gimonnet-special-club', 'espumoso', 'De 110 a 160 €', 35, '2016 Pierre Gimonnet Special Club', '160 €', 'Champagne · Cuis (Côte des Blancs) · chardonnay', '["*Special Club* es la cuvée de prestigio de los miembros del Club Trésors de Champagne, una asociación de viticultores: todos usan la misma botella y solo la sacan en buenas añadas.", "La de Gimonnet se arma con sus mejores parcelas de chardonnay, sobre todo de los grands crus Cramant y Chouilly.", "Perfil: precisión y finura; limón, flor blanca, tiza."]'::jsonb, 'el blanc de blancs de añada de la carta.', false, false),
  ('nv-vouette-et-sorbee-blanc-d-argile', 'espumoso', 'De 110 a 160 €', 36, 'NV Vouette et Sorbée Blanc d''Argile', '160 €', 'Champagne · Buxières-sur-Arce (Côte des Bar) · chardonnay · brut nature', '["Bertrand Gautherot, uno de los nombres de culto del sur de Champagne; biodinámico certificado.", "Chardonnay plantado sobre arcilla kimmeridgiana (el suelo de Chablis), fermentado en barrica, de una sola cosecha aunque no lleve añada al frente.", "Perfil: potente y vinoso para ser un blanc de blancs; fruta madura, especia, acidez firme."]'::jsonb, 'pedirlo es casi pedir un gran blanco con burbuja. Gana con aire y con copa amplia.', false, false),
  ('nv-egly-ouriet-grand-cru', 'espumoso', 'Las grandes botellas', 37, 'NV Egly-Ouriet Grand Cru', '175 €', 'Champagne · Ambonnay · mayoría de pinot noir con chardonnay', '["Francis Egly es para muchos el mejor viticultor de pinot noir de Champagne. Viñas viejas en Ambonnay, Bouzy y Verzenay.", "Fermentación en barrica y crianza larga sobre lías, muy por encima de lo habitual para un sin añada.", "Perfil: profundo, fruta roja madura, fruto seco, estructura casi de vino tinto."]'::jsonb, 'el champagne de pinot noir de la carta. Aguanta las piezas más intensas del final del menú.', false, false),
  ('nv-ar-lenoble-les-aventures-blanc-de-blancs-grand-cru-ed-5', 'espumoso', 'Las grandes botellas', 38, 'NV AR Lenoble Les Aventures Blanc de Blancs Grand Cru, Ed. #5', '245 €', 'Champagne · Chouilly (Côte des Blancs) · chardonnay · extra brut', '["*Les Aventures* es una parcela de apenas media hectárea en Chouilly, grand cru.", "No lleva añada: cada edición mezcla varias cosechas buenas de la misma parcela. La edición 5 reúne 2008, 2010 y 2012.", "Perfil: chardonnay maduro y salino, con complejidad de crianza y final apretado."]'::jsonb, 'una parcela, tres grandes añadas. Botella para ir despacio.', false, false),
  ('2018-marguet-sapience', 'espumoso', 'Las grandes botellas', 39, '2018 Marguet Sapience', '310 €', 'Champagne · 1er cru · brut nature · mínima intervención', '["La cuvée de prestigio de Benoît Marguet. Nació como un proyecto con uva de viticultores biodinámicos amigos (Léclapart, Lahaye, Laval).", "Sin sulfuroso añadido y sin dosage. *Composición de la 2018: confirmar en ficha del productor.*", "Perfil: muy vinoso, capas de fruta, especia y mineral; pide tiempo en copa."]'::jsonb, 'la gran botella de mínima intervención. Copa de Borgoña y no demasiado fría.', true, true),
  ('nv-krug-grande-cuvee-174eme-edition', 'espumoso', 'Las grandes botellas', 40, 'NV Krug Grande Cuvée 174ème Édition', '395 €', 'Champagne · Reims · pinot noir, chardonnay y meunier · brut', '["Cada edición es una mezcla de más de cien vinos de más de diez años distintos, fermentados en pequeñas barricas viejas y con unos siete años de bodega.", "La 174.ª se compuso en torno a la cosecha 2018. El código *Krug iD* de la contraetiqueta da la composición exacta.", "Perfil: el más amplio y complejo de la carta; avellana tostada, cítrico confitado, brioche, acidez que lo sostiene todo."]'::jsonb, 'no necesita explicación al cliente que la pide; sí conviene saber contar qué significa el número de edición.', false, false),
  ('2024-castell-d-encus-ekam', 'blanco', 'Por copa y hasta 95 €', 41, '2024 Castell d''Encus Ekam', '14 € copa / 54 € botella', 'Costers del Segre (Pallars Jussà, Pirineo de Lleida) · riesling con algo de albariño', '["Proyecto de Raül Bobet en Talarn, con viña en torno a los 1.000 metros: de las más altas y frescas de Catalunya.", "Fermentación en acero, sin madera. Suele conservar una punta mínima de azúcar que equilibra la acidez.", "Perfil: lima, manzana verde, flor blanca, acidez muy viva."]'::jsonb, 'es el blanco por copa. Funciona de principio a fin del omakase; si piden "un blanco" sin más, es este.', false, false),
  ('2023-billaud-simon-petit-chablis', 'blanco', 'Por copa y hasta 95 €', 42, '2023 Billaud-Simon Petit Chablis', '65 €', 'Borgoña (Chablis) · chardonnay', '["Domaine histórico de Chablis, propiedad de la casa Faiveley desde 2014.", "Petit Chablis es el primer escalón: viñas en la parte alta de las laderas. Solo acero.", "Perfil: limón, manzana, punto salino; ligero y directo."]'::jsonb, 'el chardonnay más sencillo y seguro. Ideal para sashimi de pescado blanco.', false, false),
  ('2022-domaine-de-la-renardiere-les-terrasses', 'blanco', 'Por copa y hasta 95 €', 43, '2022 Domaine de la Renardière Les Terrasses', '65 €', 'Jura (Arbois-Pupillin) · 100 % savagnin', '["Jean-Michel Petit, en Pupillin. Savagnin de viñas de unos 40 años sobre margas.", "Es un savagnin *ouillé*: la barrica se mantiene rellena, así que **no** tiene el carácter oxidativo del vin jaune. Crianza larga en madera grande.", "Perfil: piel de limón, nuez fresca, toque ahumado y salino; acidez alta."]'::jsonb, 'para el cliente curioso. Con erizo, ankimo o piezas con mucho umami es de lo mejor de la carta.', false, false),
  ('2023-vina-corrales-fino-saca-2023', 'blanco', 'Por copa y hasta 95 €', 44, '2023 Viña Corrales Fino, Saca 2023', '75 €', 'Jerez · Pago Balbaína · 100 % palomino', '["El proyecto jerezano de Peter Sisseck (Pingus): un fino de un solo viñedo sobre albariza, algo excepcional en una región de mezclas.", "Cría bajo velo de flor; se embotella una saca al año, de ahí la fecha. Unos 15 % de alcohol.", "Perfil: almendra cruda, masa de pan, tiza, final muy salino y seco."]'::jsonb, 'el fino es el vino español que mejor entiende el sushi: salinidad y umami. Se sirve frío, en copa de vino. Avisar que es un fino, no un blanco al uso.', false, false),
  ('2020-fio-falkenberg-riesling', 'blanco', 'Por copa y hasta 95 €', 45, '2020 FIO Falkenberg Riesling', '75 €', 'Mosela (Piesport) · riesling', '["FIO es el proyecto de Philipp Kettern con la familia Niepoort. Fermentación espontánea y crianza muy larga sobre lías en fudres viejos.", "Estilo seco, con poco alcohol.", "Perfil: cítrico maduro, hierbas, pizarra, textura más amplia que un riesling joven."]'::jsonb, 'riesling serio y seco, con más textura que el Ekam.', false, false),
  ('2022-pico-wines-arinto-dos-acores', 'blanco', 'Por copa y hasta 95 €', 46, '2022 Pico Wines Arinto dos Açores', '80 €', 'Azores (isla de Pico) · arinto dos Açores', '["De la cooperativa de la isla. Las viñas crecen en *currais*, pequeños corrales de piedra volcánica negra a metros del Atlántico; el paisaje es Patrimonio de la Humanidad.", "El arinto dos Açores es una variedad propia del archipiélago, distinta del arinto continental.", "Perfil: limón, yodo, sal marina; acidez muy alta."]'::jsonb, 'el vino más "de mar" de la carta. *En la carta figura como "Arinta"; el nombre correcto de la uva es arinto.*', false, false),
  ('2023-rijckaert-pouilly-fuisse-1er-cru-sur-la-roche', 'blanco', 'Por copa y hasta 95 €', 47, '2023 Rijckaert Pouilly-Fuissé 1er Cru Sur la Roche', '85 €', 'Borgoña (Mâconnais, Vergisson) · chardonnay', '["Casa fundada por Jean Rijckaert y continuada por Florent Rouve. Crianzas largas en barrica usada, sin remover lías.", "*Sur la Roche* es una parcela alta bajo la roca de Vergisson, premier cru desde la cosecha 2020.", "Perfil: chardonnay maduro pero tenso; fruta de hueso, avellana, caliza."]'::jsonb, 'el borgoña blanco con más cuerpo por debajo de 100 €.', false, false),
  ('2023-maison-reno-bourgogne-aligote', 'blanco', 'Por copa y hasta 95 €', 48, '2023 Maison Réno Bourgogne Aligoté', '90 €', 'Borgoña · 100 % aligoté', '["Proyecto personal de Réno Pacalet, hijo de Philippe Pacalet, nacido en 2023: esta es su primera añada.", "Dos parcelas a partes iguales, en Puligny-Montrachet y Cheilly-lès-Maranges. Prensado lento de racimo entero y nueve meses en acero.", "Perfil: ralladura de limón, manzana verde, piedra mojada; seco y enérgico."]'::jsonb, 'sirve para explicar la otra uva blanca de Borgoña. Muy bueno con hikarimono (caballa, sardina, kohada).', false, false),
  ('2022-domaine-du-nozay-clos-de-nozay', 'blanco', 'Por copa y hasta 95 €', 49, '2022 Domaine du Nozay Clos de Nozay', '95 €', 'Loira (Sancerre) · sauvignon blanc', '["Domaine familiar en Sainte-Gemme, en biodinámica. El *Clos* es el viñedo cercado que rodea la casa.", "Perfil: sauvignon sin exuberancia herbácea; pomelo, flor blanca, tiza."]'::jsonb, 'para quien pide sauvignon blanc o un blanco aromático pero fino.', false, false),
  ('2023-domaine-des-malandes-chablis-1er-cru-mont-de-milieu', 'blanco', 'De 105 a 145 €', 50, '2023 Domaine des Malandes Chablis 1er Cru Mont de Milieu', '105 €', 'Borgoña (Chablis) · chardonnay', '["Domaine familiar de Chablis, hoy en manos de la segunda generación.", "*Mont de Milieu* está en la orilla derecha del Serein, orientado al sur, junto a los grands crus: uno de los premiers crus más maduros y completos.", "Perfil: fruta blanca madura, concha de ostra, más amplitud que un Chablis genérico."]'::jsonb, 'el paso lógico por encima del Petit Chablis.', false, false),
  ('2018-selma-de-nin-selma-blanc', 'blanco', 'De 105 a 145 €', 51, '2018 Selma de Nin, Selma Blanc', '110 €', 'Penedès (Pla de Manlleu) · roussanne, marsanne, chenin blanc y parellada montònega · mínima intervención', '["Ester Nin y Carles Ortiz (Nin-Ortiz, Priorat). Viña de altura trabajada en biodinámica.", "Mezcla poco habitual de variedades del Ródano y del Loira con una local.", "Perfil: con ocho años tiene notas de cera, miel seca, hierbas y fruta de hueso; textura untuosa con buena acidez."]'::jsonb, 'blanco de textura, para piezas grasas o platos calientes. Es el blanco con más edad de la carta junto a los 2016 y 2017.', true, false),
  ('2020-kreydenweiss-riesling-wiebelsberg-grand-cru', 'blanco', 'De 105 a 145 €', 52, '2020 Kreydenweiss Riesling Wiebelsberg Grand Cru', '115 €', 'Alsacia (Andlau) · riesling', '["Uno de los pioneros de la biodinámica en Alsacia (desde 1989).", "*Wiebelsberg* es un grand cru de arenisca rosa: da rieslings finos, florales y secos.", "Perfil: cítrico, flor blanca, especia; seco, con más cuerpo que un Mosela."]'::jsonb, 'riesling seco de gastronomía.', false, false),
  ('2023-frederic-cossard-bourgogne-blanc-bigotes', 'blanco', 'De 105 a 145 €', 53, '2023 Frédéric Cossard Bourgogne Blanc "Bigotes"', '120 €', 'Borgoña · chardonnay · mínima intervención', '["Cossard, instalado en Saint-Romain, es uno de los referentes del vino natural en Borgoña: levaduras propias y sin sulfuroso añadido.", "*Bigotes* es su Bourgogne blanc: la puerta de entrada a su estilo.", "Perfil: fruta muy pura, cítrico, textura sedosa. Puede abrir algo reducido."]'::jsonb, 'el primer Cossard para quien quiere probar el estilo sin ir a los 430 € del Folatières.', true, false),
  ('2023-cantarina-el-godello-de-consuelo', 'blanco', 'De 105 a 145 €', 54, '2023 Cantariña, El Godello de Consuelo', '125 €', 'Bierzo (Villafranca del Bierzo) · 100 % godello', '["Bodega familiar con unas 13 hectáreas en ecológico, todas en Villafranca, y vinificación de baja intervención.", "Perfil: godello de textura, fruta blanca, hinojo, final mineral. *Detalles de crianza: a confirmar con el distribuidor.*"]'::jsonb, 'la respuesta española a un borgoña blanco.', false, true),
  ('2023-domaine-des-malandes-chablis-grand-cru-les-clos', 'blanco', 'De 105 a 145 €', 55, '2023 Domaine des Malandes Chablis Grand Cru Les Clos', '145 €', 'Borgoña (Chablis) · chardonnay', '["*Les Clos* es el mayor y, para muchos, el mejor de los siete grands crus de Chablis: el más potente y longevo.", "Perfil: concentrado, cítrico confitado, piedra, estructura para guardar. Hoy está joven."]'::jsonb, 'el techo de Chablis en la carta. Mejor con algo de aire y no demasiado frío.', false, false),
  ('2023-francois-carillon-puligny-montrachet', 'blanco', 'Las grandes botellas', 56, '2023 François Carillon Puligny-Montrachet', '175 €', 'Borgoña (Côte de Beaune) · chardonnay', '["Los Carillon son viticultores en Puligny desde hace siglos; François lleva su parte desde 2010.", "Perfil: el Puligny de manual; flor blanca, limón, almendra, tensión mineral."]'::jsonb, 'referencia para explicar Puligny frente a Meursault (más tenso y recto).', false, false),
  ('2022-boyer-de-bar-meursault-en-l-ormeau', 'blanco', 'Las grandes botellas', 57, '2022 Boyer de Bar Meursault En l''Ormeau', '195 €', 'Borgoña (Côte de Beaune) · chardonnay', '["Etiqueta de Vincent Boyer (Domaine Boyer-Martenot, Meursault) junto a su amigo Emmanuel Lucas de Bar.", "*En l''Ormeau* es una parcela de viñas viejas a nivel village, junto al pueblo.", "Perfil: Meursault clásico; más ancho y mantecoso, avellana, fruta amarilla."]'::jsonb, 'el contrapunto del Puligny de Carillon.', false, false),
  ('2021-marcel-deiss-schlossberg-grand-cru', 'blanco', 'Las grandes botellas', 58, '2021 Marcel Deiss Schlossberg Grand Cru', '210 €', 'Alsacia (Kientzheim) · mezcla de viña con base de riesling', '["Deiss defiende la *complantation*: distintas variedades plantadas y vendimiadas juntas, de modo que manda el viñedo y no la uva. Biodinámica.", "*Schlossberg*, sobre granito, fue el primer grand cru reconocido en Alsacia.", "Perfil: denso, cítrico y fruta de hueso, especias. *Los Deiss pueden llevar algo de azúcar residual: comprobar el índice de dulzor de la contraetiqueta.*"]'::jsonb, 'vino de terruño más que de variedad; para clientes que ya conocen Alsacia.', false, false),
  ('2017-benjamin-romeo-coleccion-no5-el-sauco', 'blanco', 'Las grandes botellas', 59, '2017 Benjamín Romeo, Colección Nº5 El Sauco', '230 €', 'Rioja · garnacha blanca, viura y malvasía', '["Vino de una sola parcela elaborado por Benjamín Romeo (Contador) junto a Ismael Gozalo, uno de los grandes elaboradores de blancos de Castilla.", "Perfil: blanco riojano de guarda, amplio y complejo; fruta madura, hierbas, madera integrada."]'::jsonb, 'rareza de colección. Servir a temperatura de blanco de Borgoña, no frío.', false, false),
  ('2021-eulogio-pomares-parcela-en-aios', 'blanco', 'Las grandes botellas', 60, '2021 Eulogio Pomares, Parcela en Aios', '275 €', 'Rías Baixas (Val do Salnés) · albariño', '["Eulogio Pomares es el viticúltor y enólogo de Zárate, la bodega familiar, y probablemente el nombre más respetado del albariño.", "Su línea personal de parcelarios se vinifica en madera grande (fudres de castaño o roble) y en cantidades mínimas. *Datos concretos de esta parcela: a confirmar.*", "Perfil: albariño de profundidad, nada tropical; cítrico, laurel, granito, sal."]'::jsonb, 'el gran blanco atlántico de la carta.', false, true),
  ('2022-willi-schaefer-graacher-domprobst-kabinett-no1-auction', 'blanco', 'Las grandes botellas', 61, '2022 Willi Schaefer Graacher Domprobst Kabinett Nº1, Auction', '305 €', 'Mosela (Graach) · riesling · con dulzor', '["Domaine familiar minúsculo y de culto. *Domprobst* es su gran viñedo, sobre pizarra.", "\"Auction\": botellas de un lote especial que solo se venden en la subasta anual de productores de Tréveris.", "Es un *Kabinett* clásico: poco alcohol (en torno a 8 %), azúcar residual y una acidez altísima que lo equilibra.", "Perfil: manzana, lima, pizarra, dulzor ligero y jugoso."]'::jsonb, 'hay que avisar siempre que **no es seco**. Con piezas dulces o saladas-dulces (anago con tsume, tamago) es extraordinario.', false, false),
  ('2016-joseph-drouhin-hospices-de-beaune-meursault-1er-cru', 'blanco', 'Las grandes botellas', 62, '2016 Joseph Drouhin, Hospices de Beaune Meursault 1er Cru', '340 €', 'Borgoña (Côte de Beaune) · chardonnay', '["Vino procedente de la subasta de los Hospices de Beaune: Drouhin compró la barrica y la crió.", "Las cuvées de los Hospices llevan el nombre de un benefactor. *Anotar aquí la cuvée y el climat que figuran en la etiqueta.*", "Perfil: Meursault maduro, con diez años; fruto seco, mantequilla tostada, miel."]'::jsonb, 'botella con historia; el relato de la subasta benéfica suma mucho.', false, false),
  ('2022-frederic-cossard-puligny-montrachet-1er-cru-les-folatieres', 'blanco', 'Las grandes botellas', 63, '2022 Frédéric Cossard Puligny-Montrachet 1er Cru Les Folatières', '430 €', 'Borgoña (Côte de Beaune) · chardonnay · mínima intervención', '["*Les Folatières* es el premier cru más extenso de Puligny, en la parte alta y pedregosa de la ladera.", "Elaborado sin sulfuroso añadido.", "Perfil: gran concentración con mucha pureza; cítrico, flor, piedra."]'::jsonb, 'decantar o dar aire; no servir frío.', true, false),
  ('2023-chapuis-chapuis-corton-charlemagne-grand-cru', 'blanco', 'Las grandes botellas', 64, '2023 Chapuis & Chapuis Corton-Charlemagne Grand Cru', '475 €', 'Borgoña (Côte de Beaune) · chardonnay · mínima intervención', '["Los hermanos Romain y Jean-Guillaume Chapuis, de familia de Aloxe-Corton, elaboran con uva ecológica y mínima intervención.", "*Corton-Charlemagne* es el gran grand cru blanco de la colina de Corton: potencia, acidez y capacidad de guarda.", "Perfil: muy joven todavía; denso, cítrico, mineral, con estructura."]'::jsonb, 'el blanco más caro de la carta. Copa de Borgoña grande y tiempo.', true, false),
  ('2024-chapuis-chapuis-bourgogne-cote-d-or-rouge', 'tinto', 'Por copa y hasta 100 €', 65, '2024 Chapuis & Chapuis Bourgogne Côte d''Or Rouge', '14 € copa / 45 € botella', 'Borgoña · pinot noir · mínima intervención', '["Los hermanos Chapuis elaboran con uva ecológica, levaduras propias y muy poco sulfuroso.", "*Bourgogne Côte d''Or* es una denominación regional limitada a uva de la Côte d''Or (Côte de Nuits y Côte de Beaune), un escalón por encima del Bourgogne genérico.", "Perfil: cereza ácida, frambuesa, hoja, tanino casi imperceptible."]'::jsonb, 'es el tinto por copa de referencia. Se sirve fresco. Va con akami, bonito, anago y platos calientes.', true, false),
  ('2023-4-kilos-12-volts', 'tinto', 'Por copa y hasta 100 €', 66, '2023 4 Kilos, 12 Volts', '14 € copa / 45 € botella', 'Mallorca · callet con otras variedades (habitualmente syrah, cabernet y merlot)', '["4 Kilos es el proyecto de Francesc Grimalt y Sergio Caballero en Felanitx. El nombre viene de los cuatro millones de pesetas con que arrancaron.", "La callet es la uva tinta mallorquina: poco color, poco alcohol, fruta roja y un punto terroso.", "Perfil: mediterráneo pero ligero; fruta roja, hierbas, especia."]'::jsonb, 'el tinto por copa con algo más de cuerpo que el borgoña. Dato de conversación: Sergio Caballero es uno de los fundadores del festival Sónar.', false, false),
  ('2022-dominio-do-bibei-lalama', 'tinto', 'Por copa y hasta 100 €', 67, '2022 Dominio do Bibei, Lalama', '50 €', 'Ribeira Sacra · mencía con brancellao, mouratón, sousón y garnacha', '["Bodega de referencia del valle del Bibei, con viñedo en terrazas de pizarra y granito.", "Crianza larga en madera usada y fudres; sale al mercado con años de botella.", "Perfil: fruta roja, flores, pizarra, acidez atlántica."]'::jsonb, 'la mejor relación precio-placer de los tintos. Tinto fresco español para quien no quiere Borgoña.', false, false),
  ('2022-el-mas-de-l-a-lo-noir', 'tinto', 'Por copa y hasta 100 €', 68, '2022 El Mas de l''A, Lo Noir', '65 €', 'Priorat (La Morera de Montsant) · garnacha y pinot noir', '["Proyecto de Alfredo Arribas que busca un Priorat distinto: viña ecológica a más de 500 metros, menos alcohol, taninos sedosos.", "La mezcla de garnacha con pinot noir es muy poco habitual. Crianza en madera de 500 y 600 litros; se embotella sin filtrar.", "Perfil: fruta roja pura, flores, tensión mineral; nada que ver con el Priorat potente de siempre."]'::jsonb, 'para sorprender a quien cree que Priorat es sinónimo de vino pesado.', false, false),
  ('2022-josep-foraster-la-robina', 'tinto', 'Por copa y hasta 100 €', 69, '2022 Josep Foraster, La Robina', '70 €', 'Conca de Barberà (Montblanc)', '["Bodega familiar en ecológico, la gran defensora del **trepat**: una uva tinta local de poco color, mucha acidez y nota de pimienta blanca. De unas 1.100 hectáreas que hay en el mundo, unas 1.000 están en esta comarca.", "*Variedad y elaboración de La Robina: a confirmar con la ficha del productor o el distribuidor.*"]'::jsonb, 'hasta confirmar la ficha, presentarlo como tinto ligero de la Conca de Barberà.', false, true),
  ('2023-domaine-saint-cyr-moulin-a-vent-la-bruyere', 'tinto', 'Por copa y hasta 100 €', 70, '2023 Domaine Saint-Cyr, Moulin-à-Vent La Bruyère', '75 €', 'Beaujolais · gamay · mínima intervención', '["Raphaël Saint-Cyr trabaja en ecológico y vinifica con racimo entero y muy poco sulfuroso.", "*Moulin-à-Vent* es el cru más estructurado de los diez del Beaujolais, sobre granito; *La Bruyère* es una de sus parcelas.", "Perfil: cereza negra, violeta, especia; jugoso pero con columna."]'::jsonb, 'gamay serio. Alternativa a un pinot noir a mitad de precio.', true, false),
  ('2023-bruma-agricola-bruma-de-arenero', 'tinto', 'Por copa y hasta 100 €', 71, '2023 Bruma Agrícola, Bruma de Arenero', '80 €', 'Cebreros (Sierra de Gredos, Ávila) · garnacha', '["Cebreros es la denominación más joven de Gredos: garnacha de viña vieja en vaso, en altura, sobre granito. El estilo de la zona es de poco color y mucha finura.", "*Datos de esta cuvée concreta: a confirmar.*", "Perfil esperable: fresa ácida, flores, monte bajo, tanino de arena."]'::jsonb, '"el pinot noir de España" es una forma rápida, aunque inexacta, de situar la garnacha de Gredos.', false, true),
  ('2023-domaine-de-la-renardiere-trousseau-a-la-dame', 'tinto', 'Por copa y hasta 100 €', 72, '2023 Domaine de la Renardière, Trousseau à la Dame', '80 €', 'Jura (Arbois-Pupillin) · trousseau · mínima intervención', '["El *trousseau à la dame* es una variante antigua del trousseau, de racimo más suelto y grano pequeño.", "Perfil: color claro, fruta roja, pimienta, un punto terroso; acidez viva."]'::jsonb, 'el tinto más ligero y singular de la carta. *En la carta aparece como "Trousseau de la Dame"; el productor lo escribe "à la Dame".*', true, false),
  ('2022-sandrone-nebbiolo-d-alba-valmaggiore', 'tinto', 'Por copa y hasta 100 €', 73, '2022 Sandrone, Nebbiolo d''Alba Valmaggiore', '90 €', 'Piamonte (Roero) · nebbiolo', '["Sandrone es una de las grandes casas de Barolo. *Valmaggiore* es un anfiteatro de arena muy empinado en el Roero, al otro lado del río Tanaro.", "La arena da un nebbiolo más aromático y de tanino más suave que un Barolo.", "Perfil: rosa, fresa, especia; tanino presente pero fino."]'::jsonb, 'la manera amable de entrar al nebbiolo.', false, false),
  ('2022-domaine-de-la-renardiere-pinot-noir', 'tinto', 'Por copa y hasta 100 €', 74, '2022 Domaine de la Renardière, Pinot Noir', '100 €', 'Jura (Arbois-Pupillin) · pinot noir · mínima intervención', '["Pinot noir del Jura: más ligero, más ácido y más terroso que uno de Borgoña.", "Perfil: guinda, tierra húmeda, hierbas."]'::jsonb, 'para quien pide pinot noir y quiere salir de Borgoña.', true, false),
  ('2023-david-duband-gevrey-chambertin', 'tinto', 'De 145 a 275 €', 75, '2023 David Duband, Gevrey-Chambertin', '145 €', 'Borgoña (Côte de Nuits) · pinot noir', '["Duband trabaja en ecológico y vinifica con una proporción alta de racimo entero, lo que da perfume y frescura.", "Gevrey es el pueblo de los tintos más estructurados de la Côte de Nuits.", "Perfil: cereza negra, especias, tallo; elegante para ser Gevrey."]'::jsonb, 'el borgoña tinto de pueblo de referencia.', false, false),
  ('2016-la-rioja-alta-gran-reserva-904', 'tinto', 'De 145 a 275 €', 76, '2016 La Rioja Alta, Gran Reserva 904', '185 €', 'Rioja (Haro) · tempranillo con graciano', '["La casa clásica por excelencia. El nombre recuerda 1904, año de la fusión con Bodegas Ardanza.", "Cuatro años en barrica de roble americano fabricada por la propia bodega, con trasiegas a mano.", "Perfil: Rioja clásico; cereza en licor, coco, tabaco, cuero fino, acidez alta y tanino pulido."]'::jsonb, 'el clásico español que más clientes reconocen. Su acidez y su tanino suave lo hacen más compatible con la barra de lo que parece.', false, false),
  ('2020-sandrone-barolo-le-vigne', 'tinto', 'De 145 a 275 €', 77, '2020 Sandrone, Barolo Le Vigne', '200 €', 'Piamonte · nebbiolo', '["*Le Vigne* sigue la tradición antigua de Barolo: mezclar viñedos de distintos pueblos en lugar de embotellar uno solo. Reúne parcelas de Serralunga, Castiglione Falletto, Barolo y Novello.", "Perfil: rosa seca, cereza, alquitrán, regaliz; mucho tanino y mucha acidez."]'::jsonb, 'decantar. Es el tinto más tánico de la carta: mejor con carne o al final.', false, false),
  ('2022-niepoort-charme', 'tinto', 'De 145 a 275 €', 78, '2022 Niepoort, Charme', '210 €', 'Douro · viña vieja con mezcla de variedades (tinta roriz, touriga franca y otras)', '["La idea de Dirk Niepoort de hacer un \"borgoña\" en el Douro: viñas viejas de Vale de Mendiz, pisado con raspones en lagar, maceración corta y crianza en barrica francesa.", "Perfil: fruta roja, flores, madera fina; mucha suavidad."]'::jsonb, 'el nombre lo dice. Tinto de seda.', false, false),
  ('2023-frederic-cossard-gevrey-chambertin-les-genevrieres-qvevris', 'tinto', 'De 145 a 275 €', 79, '2023 Frédéric Cossard, Gevrey-Chambertin Les Genevrières "Qvevris"', '240 €', 'Borgoña (Côte de Nuits) · pinot noir · mínima intervención', '["*Qvevri* es la tinaja de barro georgiana. Cossard cría este vino en tinaja en lugar de barrica: nada de aporte de madera, fruta desnuda.", "Sin sulfuroso añadido.", "Perfil: fruta roja muy nítida, tacto terroso, tanino fino."]'::jsonb, 'buena historia para contar (Borgoña en ánfora). Dar aire.', true, false),
  ('2023-chapuis-chapuis-corton-grand-cru', 'tinto', 'De 145 a 275 €', 80, '2023 Chapuis & Chapuis, Corton Grand Cru', '275 €', 'Borgoña (Côte de Beaune) · pinot noir · mínima intervención', '["Corton es el único grand cru tinto de la Côte de Beaune, y la colina de origen de la familia Chapuis.", "Perfil: pinot noir con estructura y fondo terroso; todavía muy joven."]'::jsonb, 'decantar. Grand cru a un precio contenido para lo que es Borgoña.', true, false),
  ('2023-frederic-cossard-morey-saint-denis-1er-cru-monts-luisants', 'tinto', 'Las grandes botellas', 81, '2023 Frédéric Cossard, Morey-Saint-Denis 1er Cru Monts Luisants', '310 €', 'Borgoña (Côte de Nuits) · pinot noir · mínima intervención', '["*Monts Luisants* es un premier cru en lo alto de la ladera de Morey, encima del grand cru Clos de la Roche.", "Perfil: perfume, fruta roja, tensión de altura."]'::jsonb, 'el gran tinto de Cossard en la carta.', true, false),
  ('2019-dominio-del-aguila-penas-aladas-gran-reserva', 'tinto', 'Las grandes botellas', 82, '2019 Dominio del Águila, Peñas Aladas Gran Reserva', '360 €', 'Ribera del Duero (La Aguilera) · viña muy vieja de tempranillo con otras variedades mezcladas', '["Jorge Monzón e Isabel Rodero. Viñedos prefiloxéricos en altura donde el tempranillo convive con blanca del país, bobal, garnacha y otras.", "Racimo entero pisado, crianza muy larga en barrica. El resultado no se parece a la Ribera potente habitual.", "Perfil: profundo pero fresco; fruta negra, flores, especia, tiza."]'::jsonb, 'decantar. Una de las grandes botellas españolas de hoy.', false, false),
  ('2019-joseph-drouhin-vosne-romanee-1er-cru', 'tinto', 'Las grandes botellas', 83, '2019 Joseph Drouhin, Vosne-Romanée 1er Cru', '410 €', 'Borgoña (Côte de Nuits) · pinot noir', '["Vosne-Romanée es el pueblo más cotizado de Borgoña tinta: perfume de especias y textura de seda.", "Drouhin es una de las grandes casas de Beaune, con estilo elegante y poca extracción. *Si la etiqueta indica el climat, anotarlo aquí.*", "Perfil: 2019 fue una añada cálida y concentrada; fruta madura, especia dulce, tanino sedoso."]'::jsonb, 'borgoña clásico de gran pueblo, ya con algo de botella.', false, false),
  ('2017-benjamin-romeo-contador', 'tinto', 'Las grandes botellas', 84, '2017 Benjamín Romeo, Contador', '470 €', 'Rioja (San Vicente de la Sonsierra) · tempranillo de viña vieja, con algo de garnacha y graciano', '["El vino que puso a Benjamín Romeo en el mapa: nació como vino de garaje en una cueva bajo el castillo de San Vicente y llegó a los 100 puntos Parker.", "Rioja moderna: crianza en barrica francesa nueva, mucha concentración.", "2017 fue el año de la gran helada de abril en Rioja: producción muy corta.", "Perfil: potente, fruta negra, tostados finos, tanino abundante."]'::jsonb, 'decantar siempre. No es un vino para acompañar nigiri; se recomienda con conocimiento de causa.', false, false),
  ('2011-la-rioja-alta-gran-reserva-890-seleccion-especial', 'tinto', 'Las grandes botellas', 85, '2011 La Rioja Alta, Gran Reserva 890 Selección Especial', '485 €', 'Rioja (Haro) · tempranillo con graciano y mazuelo', '["El tope de gama de La Rioja Alta; el nombre recuerda 1890, año de fundación. *Selección Especial* se reserva para las añadas que la bodega considera excepcionales.", "Seis años en barrica de roble americano y largo reposo en botella antes de salir.", "Perfil: Rioja clásico en su versión más fina; fruta en licor, especias dulces, tabaco, caoba, una acidez que lo mantiene vivo."]'::jsonb, 'con quince años está en un gran momento. Servir con cuidado por si hay sedimento. *Confirmar añada en la etiqueta.*', false, true),
  ('yamazaki-umeshu-barrel-aged', 'whisky', 'Whisky japonés', 86, 'Yamazaki Umeshu Barrel-Aged', '18 €', null, '["**A confirmar con la botella en mano.** Por el nombre, lo más probable es que sea el *umeshu* de Suntory envejecido en barricas de whisky de la destilería Yamazaki: un licor de ume (en torno a 16–17 %), no un whisky.", "Si es eso: dulce, ciruela, almendra, con notas de vainilla y madera de la barrica."]'::jsonb, 'se sirve frío o con hielo, como final dulce. Si se confirma que es umeshu, tendría más sentido listarlo en "Aperitivo – Final".', false, true),
  ('hibiki-blender-s-choice', 'whisky', 'Whisky japonés', 87, 'Hibiki Blender''s Choice', '22 €', 'Suntory · blended · 43 %', '["Mezcla de maltas de Yamazaki y Hakushu con grano de Chita. Esta versión incluye whiskies envejecidos en barrica de vino, que le dan una nota frutal y dulce.", "Perfil: redondo, miel, fruta madura, madera suave."]'::jsonb, 'el más fácil de la lista. Para quien quiere "un whisky japonés" sin más.', false, false),
  ('kuju-new-born-peated-3', 'whisky', 'Whisky japonés', 88, 'Kuju New Born Peated #3', '22 €', 'Destilería Kuju · Oita (Kyushu) · destilado joven ahumado', '["Destilería nueva, terminada a fines de 2020 al pie de los montes Kuju, a unos 600 metros, en el solar de una antigua bodega de sake. La fundó Shoji Utoda, organizador del festival Whisky Talk Fukuoka.", "*New Born*: todavía no tiene los tres años. Las tiradas anteriores salieron a alta graduación. *Graduación y barrica de esta tirada: mirar la etiqueta.*", "Perfil esperable: cereal, fruta blanca, humo, mucho nervio."]'::jsonb, 'para curiosos. Es una foto de una destilería que está naciendo.', false, false),
  ('yamazaki-smoky-batch-the-third', 'whisky', 'Whisky japonés', 89, 'Yamazaki Smoky Batch "The Third"', '24 €', 'Suntory · single malt · 43 %', '["Edición limitada, originalmente exclusiva de duty free, que muestra el lado ahumado y poco conocido de Yamazaki, la destilería de malta más antigua de Japón.", "Perfil: la fruta madura típica de Yamazaki con una capa de humo suave."]'::jsonb, 'ahumado elegante, no agresivo.', false, false),
  ('akkeshi-keichitsu', 'whisky', 'Whisky japonés', 90, 'Akkeshi Keichitsu', '24 €', 'Destilería Akkeshi · Hokkaido · single malt ligeramente ahumado · 55 %', '["Akkeshi está en la costa este de Hokkaido y se inspira en Islay: mar, niebla y turba local.", "Es la décima entrega de su serie de los 24 *sekki* (las estaciones del calendario tradicional). *Keichitsu* es el período de principios de marzo en que la tierra se templa y los insectos despiertan.", "Mezcla de barricas de mizunara de Hokkaido, bourbon, jerez y vino tinto. Sin filtrado en frío.", "Perfil: mandarina, chocolate negro, sal, incienso, humo ligero."]'::jsonb, 'potente por graduación; ofrecer agua.', false, false),
  ('shizuoka-pot-still-k', 'whisky', 'Whisky japonés', 91, 'Shizuoka Pot Still "K"', '26 €', 'Destilería Shizuoka · single malt · en torno a 55 %', '["Destilería fundada en 2016. La \"K\" es por su alambique: un pot still rescatado de la mítica destilería Karuizawa, cerrada hace años. Todo el whisky de esta botella pasó por ese alambique.", "Hay ediciones con cebada japonesa y con cebada importada. *Anotar cuál tenemos.*", "Perfil: lichi, pasas, miel, especias."]'::jsonb, 'la historia de Karuizawa vende sola entre aficionados.', false, false),
  ('hakushu-japanese-forest-bittersweet-edition', 'whisky', 'Whisky japonés', 92, 'Hakushu "Japanese Forest" Bittersweet Edition', '28 €', 'Suntory · single malt · 43 %', '["Edición limitada de 2023 para duty free. Hakushu, en los Alpes japoneses, suele ser fresco y herbal; esta versión está envejecida en roble español y es mucho más oscura.", "Perfil: miel de manuka, mermelada de naranja, cacao, final de espresso."]'::jsonb, 'el más goloso y "de postre" de los single malt. *En la carta figura como "The Forest".*', false, false),
  ('oso-brewery-cerveza-citrus-33-cl', 'aperitivo', 'Aperitivo – Final', 93, 'OSO Brewery, Cerveza Citrus (33 cl)', '7,5 €', null, '["Cerveza artesana de Madrid. *Estilo exacto y graduación: a confirmar con la lata o botella.*"]'::jsonb, 'la única cerveza de la carta.', false, true),
  ('heiwa-shuzo-yuzu-spritz', 'aperitivo', 'Aperitivo – Final', 94, 'Heiwa Shuzo, Yuzu Spritz', '12 €', null, '["Heiwa Shuzo es la bodega de Wakayama que elabora el sake KID. Su línea *Tsuru-ume* son licores de fruta local con base de sake, sin aromas ni colorantes.", "El *yuzushu* lleva una proporción muy alta de zumo de yuzu de Wakayama y ronda el 7 % de alcohol: ácido, intenso, apenas dulce.", "*\"Spritz\" indicaría que se sirve alargado con soda; anotar aquí la receta de la casa.*"]'::jsonb, 'aperitivo perfecto antes del omakase: cítrico, ligero, abre el apetito.', false, false),
  ('heiwa-shuzo-umeshu-clasico', 'aperitivo', 'Aperitivo – Final', 95, 'Heiwa Shuzo, Umeshu Clásico', '12 €', null, '["*Umeshu*: licor de ume, la fruta japonesa emparentada con el albaricoque (suele traducirse \"ciruela\"). Se macera la fruta entera con azúcar en alcohol o sake.", "Wakayama es la gran zona de ume de Japón; Heiwa trabaja directamente con agricultores locales y elabora umeshu desde 1995.", "Perfil: agridulce, albaricoque, almendra del hueso."]'::jsonb, 'con hielo como aperitivo, o solo y frío al final.', false, false),
  ('mii-no-kotobuki-umeshu-amaretto', 'aperitivo', 'Aperitivo – Final', 96, 'Mii no Kotobuki, Umeshu "Amaretto"', '16 €', null, '["De la misma bodega de Fukuoka que elabora el **Biden** de la carta de sakes. La base no es alcohol neutro sino sake junmai añejo (koshu), en el que se macera el ume unos seis meses.", "El apodo \"amaretto\" viene del aroma a almendra que sueltan los huesos de la fruta. Ronda el 10 % de alcohol.", "Perfil: más profundo y menos dulce que un umeshu corriente; ciruela, almendra, caramelo del sake viejo."]'::jsonb, 'buen puente con la carta de sakes: quien tomó Biden puede cerrar con el umeshu hecho sobre ese mismo tipo de sake.', false, false),
  ('valdespino-moscatel-toneles-viejisimo-1930', 'aperitivo', 'Aperitivo – Final', 97, 'Valdespino, Moscatel Toneles Viejísimo (~1930)', '40 €', 'Jerez · moscatel', '["Uno de los vinos dulces más legendarios de España. Procede de una solera minúscula de unos pocos toneles, con una edad media de muchas décadas; de ahí la referencia a 1930.", "Uva moscatel pasificada al sol, fortificada y envejecida hasta quedar casi negra y densa como un jarabe.", "Perfil: pasas, dátil, café, cacao, yodo, una acidez que evita que empalague; interminable."]'::jsonb, 'se sirve en dosis pequeña, como un postre en sí mismo. Es una de las joyas de la carta y merece que se cuente.', false, false),
  ('agua-sin-gas-solan-de-cabras', 'sin-alcohol', 'Sin alcohol', 98, 'Agua sin gas, Solán de Cabras', '4 €', null, '["Manantial de Beteta (Cuenca). Mineralización baja, sabor neutro: no interfiere con el pescado ni con el sake."]'::jsonb, null, false, false),
  ('agua-con-gas-vichy-catalan', 'sin-alcohol', 'Sin alcohol', 99, 'Agua con gas, Vichy Catalan', '4 €', null, '["Agua termal de Caldes de Malavella (Girona). Tiene mucho bicarbonato y sodio, por eso sabe claramente salada. Conviene avisar a quien no la conozca."]'::jsonb, null, false, false),
  ('iyoshi-cola-classic-edition', 'sin-alcohol', 'Sin alcohol', 100, 'Iyoshi Cola, Classic Edition', '9 €', null, '["Cola artesanal de Tokyo creada por Kola Kobayashi a partir de las recetas del taller de medicina herbal *kampo* de su abuelo. Nuez de cola, especias y cítricos; menos dulce y mucho más especiada que una cola industrial."]'::jsonb, 'la Iyoshi Cola es la opción sin alcohol con historia. Para quien no bebe, es la que se recomienda.', false, false)
insert into public.guia_capitulos (slug, area, titulo, orden, bloques) values
  ('como-usar-esta-guia', 'general', 'Cómo usar esta guía', 1, '[{"t": "p", "x": "Esta guía reúne todo lo que servimos en la barra: 20 sakes, la carta de vinos del 17 de noviembre de 2026, whiskies, aperitivos y bebidas sin alcohol. Está pensada para estudiar, no para recitar: el objetivo es entender por qué cada bebida sabe como sabe."}, {"t": "p", "x": "Cada ficha sigue el mismo orden:"}, {"t": "ul", "items": ["**Quién y dónde**: productor, zona y tipo.", "**Qué lo hace distinto**: uva o arroz, método y datos técnicos que conviene saber.", "**Cómo sabe**: el perfil en pocas palabras.", "**En sala**: cuándo ofrecerlo y cómo contarlo en una frase."]}, {"t": "p", "x": "Tres reglas de la casa:"}, {"t": "ol", "items": ["Si no sabés un dato, no lo inventes: decí que lo consultás. Un dato falso dicho con seguridad cuesta más que un \"lo averiguo\".", "Primero se pregunta, después se recomienda: qué suele beber el cliente, cuánto quiere gastar y en qué momento del menú está.", "Lo que dice la etiqueta manda. Las añadas y las partidas cambian; ante la duda, se lee la contraetiqueta."]}, {"t": "p", "x": "Los datos marcados como *a confirmar* no pudieron verificarse con la bodega o el importador y hay que cotejarlos con la botella."}]'::jsonb),
  ('fundamentos-de-sake', 'sake', 'Fundamentos de sake', 2, '[{"t": "p", "x": "El sake es un fermentado de arroz, no un destilado ni un vino: el almidón del arroz se convierte en azúcar y el azúcar en alcohol al mismo tiempo, en la misma cuba. Esa \"fermentación múltiple en paralelo\" es lo que lo distingue de la cerveza y del vino."}, {"t": "h", "n": 3, "x": "Los cuatro ingredientes"}, {"t": "ul", "items": ["**Arroz**: variedades de sake (Yamada Nishiki, Omachi, Gohyakumangoku, Kame no O) con el almidón concentrado en el centro del grano.", "**Agua**: blanda da sakes suaves y lentos; dura da sakes más secos y firmes.", "**Koji**: arroz inoculado con el moho *Aspergillus oryzae*, que aporta las enzimas que transforman el almidón en azúcar. El koji amarillo es el habitual; el koji blanco, propio del shochu, produce ácido cítrico y da sakes muy ácidos.", "**Levadura**: añadida (cepas seleccionadas) o ambiente (la que vive en la bodega)."]}, {"t": "h", "n": 3, "x": "Pulido y categorías"}, {"t": "p", "x": "El *seimaibuai* indica cuánto grano queda después de pulir: 60 % significa que se eliminó el 40 %. Al pulir se quitan proteínas y grasas del exterior, y el sake gana finura y aroma a costa de cuerpo."}, {"t": "table", "head": ["Categoría", "Pulido máximo", "Alcohol añadido"], "rows": [["Junmai", "sin mínimo", "no"], ["Junmai ginjo", "60 %", "no"], ["Junmai daiginjo", "50 %", "no"], ["Honjozo", "70 %", "sí"], ["Ginjo", "60 %", "sí"], ["Daiginjo", "50 %", "sí"]]}, {"t": "p", "x": "La categoría marca un mínimo, no un techo, y es voluntaria: algunas bodegas (Nichinichi, Senkin) no la declaran. Si un cliente pregunta, la respuesta correcta es \"la bodega no la publica\"."}, {"t": "h", "n": 3, "x": "El pie de cuba (shubo o moto)"}, {"t": "p", "x": "Es el cultivo inicial de levadura. Necesita ácido láctico para protegerse de bacterias, y la forma de conseguirlo define el estilo."}, {"t": "table", "head": ["Método", "Cómo consigue el ácido láctico", "Resultado habitual"], "rows": [["Sokujo", "se añade ácido láctico; es el método moderno", "limpio y directo"], ["Kimoto", "bacterias lácticas naturales, machacando el arroz", "más acidez, umami y estructura"], ["Yamahai", "como el kimoto, sin machacar", "más salvaje, lácteo, con cuerpo"], ["Bodaimoto", "arroz crudo en agua que se agria sola; esa agua ácida arranca el pie", "agridulce y antiguo, origen del kimoto"]]}, {"t": "h", "n": 3, "x": "Palabras de etiqueta"}, {"t": "ul", "items": ["**Nama**: sin pasteurizar. Siempre en frío.", "**Genshu**: sin diluir con agua.", "**Muroka**: sin filtrar con carbón.", "**Arabashiri / nakagumi / seme**: primera, media y última fracción del prensado.", "**Koshu**: añejado.", "**Kijoshu**: parte del agua se sustituye por sake; dulce y denso.", "**Nihonshudo (SMV)**: densidad; valores positivos tienden a seco, negativos a dulce. Solo orienta: la acidez cambia la percepción."]}, {"t": "h", "n": 3, "x": "Conservación y servicio"}, {"t": "ul", "items": ["Todo el sake de la barra vive a 5 °C. Los nama y los de fermentación natural no salen nunca de la cámara.", "Las botellas se guardan de pie y lejos de la luz.", "Los ginjo y daiginjo aromáticos se sirven fríos y en copa de vino; los yamahai, los secos rústicos y los añejos admiten temperatura ambiente o templado.", "Una botella abierta se anota con fecha: los nama evolucionan en días, los añejos aguantan semanas."]}]'::jsonb),
  ('intro-sake', 'sake', 'Los sakes de la barra', 3, '[{"t": "p", "x": "Son 20 sakes ordenados por perfil de sala. El maridaje de sake cuesta 65 € por persona; los precios entre paréntesis son copa / jarra según la carta impresa, y los que no llevan precio se sirven fuera de carta o en maridaje."}]'::jsonb),
  ('fundamentos-de-vino-para-la-barra', 'vino', 'Fundamentos de vino para la barra', 4, '[{"t": "h", "n": 3, "x": "Por qué esta carta es así"}, {"t": "p", "x": "La selección sigue una lógica: vinos que no tapen el pescado ni peleen con el shari. Eso explica casi todo lo que hay y lo que no hay."}, {"t": "ul", "items": ["**Acidez alta.** Limpia la grasa del toro o del buri igual que el gari, y sostiene el vinagre del arroz. Por eso mandan Champagne, Chablis, riesling, albariño y godello.", "**Poca madera nueva.** El tostado y la vainilla de la barrica nueva se montan encima del pescado. Los blancos de la carta fermentan en inox, fudres o barricas usadas; cuando hay madera, está integrada.", "**Tanino bajo en tintos.** El tanino con el umami se vuelve amargo, y el hierro del tinto con el pescado azul da un regusto metálico. De ahí tanta pinot noir, gamay, trousseau, garnacha de altura y mencía: tintos de color claro y tanino fino.", "**Burbuja.** El carbónico y la acidez del champagne hacen el mismo trabajo que un sake seco: resetean la boca entre piezas. Es el comodín más seguro de la carta."]}, {"t": "h", "n": 3, "x": "Champagne en diez ideas"}, {"t": "ol", "items": ["**Método tradicional.** Se hace un vino base tranquilo; se embotella con azúcar y levaduras (*tirage*) y fermenta por segunda vez dentro de la botella. El gas queda atrapado.", "**Lías.** Las levaduras muertas quedan en la botella meses o años. Cuanto más tiempo, más notas de pan, brioche y fruto seco, y burbuja más fina. Mínimo legal: 15 meses para un sin añada, 3 años para un millésimé.", "**Degüelle.** Se expulsan las lías y se rellena con el licor de expedición. La fecha de degüelle (si figura en la contraetiqueta) dice cuán fresca está la botella.", "**Dosage.** El azúcar del licor de expedición: *brut nature / dosage zéro / non dosé* (0–3 g/L, sin azúcar añadido), *extra brut* (0–6 g/L), *brut* (hasta 12 g/L). En la carta casi todo es extra brut o brut nature: perfil seco y filoso.", "**Tres uvas.** Chardonnay (tensión, cítrico, tiza), pinot noir (estructura, fruta roja) y meunier (fruta, redondez, accesibilidad).", "**Blanc de blancs / blanc de noirs.** Blanco hecho solo con uva blanca (chardonnay) o solo con uva tinta (pinot noir y/o meunier) prensada sin color.", "**Zonas.** *Montagne de Reims* (pinot noir: Ambonnay, Bouzy, Ludes, Vrigny), *Vallée de la Marne* (meunier: Damery, Dizy, Moussy), *Côte des Blancs* (chardonnay sobre tiza: Avize, Cramant, Chouilly, Le Mesnil, Vertus, Cuis), *Côte de Sézanne* (chardonnay más maduro, al sur) y *Côte des Bar* o Aube (pinot noir sobre kimmeridgiano, el mismo suelo de Chablis).", "**Grand cru y premier cru.** En Champagne lo que se clasifica es el pueblo entero: 17 pueblos grand cru y 42 premier cru.", "**NV, añada y reserva perpetua.** Un sin añada (NV) mezcla la cosecha base con vinos de reserva de años anteriores. Un millésimé es de un solo año. Una *reserva perpetua* o solera es un depósito que nunca se vacía: cada año se saca una parte y se rellena con vino nuevo, así que contiene un poco de todas las cosechas desde que se inició.", "**Quién lo hace.** *RM* (récoltant-manipulant) es el viticultor que elabora con su propia uva; *NM* (négociant-manipulant) es la casa que además compra uva. La carta es mayormente de viticultores, con tres casas grandes como referencia clásica: Charles Heidsieck, Jacquesson y Krug."]}, {"t": "h", "n": 3, "x": "Corpinnat"}, {"t": "p", "x": "No es una denominación de origen sino una marca colectiva de elaboradores del Penedès que salieron de la DO Cava. Exige uva 100 % ecológica y vendimiada a mano, al menos 90 % de variedades autóctonas (xarel·lo, macabeu, parellada), vinificación íntegra en la propiedad y un mínimo de 18 meses de crianza. En la carta: Recaredo, Llopart y Bufadors. Para el cliente: \"el espumoso catalán de método tradicional con las reglas más estrictas\"."}, {"t": "h", "n": 3, "x": "Borgoña: cómo se lee una etiqueta"}, {"t": "p", "x": "Dos uvas (chardonnay en blanco, pinot noir en tinto) y una jerarquía de cuatro escalones que explica los precios de la carta:"}, {"t": "table", "head": ["Nivel", "Qué dice la etiqueta", "Ejemplo en carta"], "rows": [["Regional", "Bourgogne, Bourgogne Côte d''Or, Bourgogne Aligoté", "Chapuis Bourgogne Côte d''Or Rouge, Cossard Bigotes"], ["Village", "El nombre del pueblo", "Carillon Puligny-Montrachet, Duband Gevrey-Chambertin"], ["Premier cru", "Pueblo + \"1er Cru\" + nombre de la parcela", "Cossard Puligny 1er Cru Les Folatières"], ["Grand cru", "Solo el nombre del viñedo", "Chapuis Corton-Charlemagne, Malandes Chablis Les Clos"]]}, {"t": "ul", "items": ["**Chablis** está aparte, al norte: chardonnay sobre suelo kimmeridgiano (marga con fósiles de ostra), casi siempre sin madera nueva. Su escala es Petit Chablis → Chablis → Chablis 1er Cru → Chablis Grand Cru.", "**Côte de Beaune** es la zona de los grandes blancos: Meursault (más ancho y mantecoso), Puligny-Montrachet (más tenso y mineral), Corton-Charlemagne (potencia y acidez).", "**Côte de Nuits** es la zona de los grandes tintos: Gevrey-Chambertin (estructura), Morey-Saint-Denis, Vosne-Romanée (perfume y seda).", "**Mâconnais**, al sur: Pouilly-Fuissé, chardonnay más solar; tiene premiers crus desde la cosecha 2020.", "**Aligoté** es la otra uva blanca de Borgoña: más ácida y ligera que el chardonnay.", "**Hospices de Beaune**: los vinos del hospital histórico de Beaune se subastan en barrica cada noviembre; una casa (en la carta, Joseph Drouhin) compra la barrica y hace la crianza."]}, {"t": "h", "n": 3, "x": "Otras regiones de la carta, en una línea"}, {"t": "ul", "items": ["**Jura** (este de Francia): savagnin y chardonnay en blanco; trousseau, poulsard y pinot noir en tinto. Vinos ligeros, de mucha acidez.", "**Alsacia**: riesling seco y con cuerpo; 51 grands crus con suelos muy distintos entre sí.", "**Mosela** (Alemania): riesling sobre pizarra, poco alcohol. *Kabinett* indica la categoría de madurez más ligera y suele llevar azúcar residual.", "**Sancerre** (Loira): sauvignon blanc sobre caliza y sílex.", "**Jerez**: palomino criado bajo velo de flor (fino) o moscatel pasificado y envejecido décadas.", "**Rías Baixas, Bierzo, Ribeira Sacra**: el noroeste atlántico; albariño, godello y mencía.", "**Rioja y Ribera del Duero**: tempranillo; en la carta aparecen como grandes botellas de guarda.", "**Piamonte**: nebbiolo, color claro pero mucho tanino y acidez (Barolo, Nebbiolo d''Alba).", "**Douro**: tintos de viña vieja con mezcla de variedades portuguesas."]}, {"t": "h", "n": 3, "x": "Mínima intervención"}, {"t": "p", "x": "En la carta hay vinos señalados como de mínima intervención. La idea: viña en ecológico o biodinámico, fermentación con levaduras propias de la uva, sin correcciones, sin clarificar ni filtrar y con muy poco o ningún sulfuroso añadido. Los marcados hoy son **Frédéric Cossard, Chapuis & Chapuis, Domaine Saint-Cyr, Domaine de la Renardière (Trousseau y Pinot Noir), Selma de Nin, Marguet y Bufadors**."}, {"t": "p", "x": "Qué implica en sala:"}, {"t": "ul", "items": ["Pueden abrir con algo de reducción (fósforo, cerilla) o con una punta de gas: se va con aire. Conviene servir y dejar que el cliente lo vea evolucionar.", "Son más sensibles a la temperatura y al transporte. Botella que sale rara, se avisa antes de servirla.", "No es sinónimo de \"vino raro\". Los de esta carta son limpios y precisos; si el cliente teme los naturales turbios, se le puede tranquilizar."]}, {"t": "h", "n": 3, "x": "Servicio"}, {"t": "p", "x": "*Las pautas de esta sección son una propuesta de trabajo; las ajusta Manu.*"}, {"t": "table", "head": ["Tipo", "Temperatura orientativa", "Copa"], "rows": [["Champagne y Corpinnat", "8–10 °C (cuvées de prestigio, 10–12 °C)", "Copa de vino blanco, no flauta"], ["Blancos ligeros (Chablis, riesling, fino)", "8–10 °C", "Blanco"], ["Blancos de Borgoña village en adelante", "11–13 °C", "Borgoña"], ["Tintos ligeros (pinot, gamay, trousseau)", "14–15 °C", "Borgoña"], ["Tintos de guarda (Rioja, Ribera, Barolo)", "16–17 °C", "Burdeos / Borgoña según estructura"]]}, {"t": "ul", "items": ["Una botella rinde **5 copas**.", "Los tintos ligeros se sirven algo frescos: en la barra ganan mucho con el pescado.", "Los blancos caros no se sirven helados: el frío tapa justo lo que el cliente está pagando.", "Decantar tiene sentido en tintos de guarda jóvenes (Barolo, Peñas Aladas, Contador) y en algunos blancos de Cossard o Chapuis que salen cerrados. Se pregunta siempre antes.", "Orden lógico si una mesa pide varias botellas: burbuja → blanco ligero → blanco con cuerpo → tinto."]}]'::jsonb),
  ('intro-espumoso', 'espumoso', 'Champagnes y espumosos', 5, '[{"t": "p", "x": "Veinte referencias, todas por botella. Van en el orden de la carta (de menor a mayor precio). Los tres Corpinnat están intercalados; el resto es Champagne."}, {"t": "p", "x": "**Mapa rápido para recomendar**"}, {"t": "table", "head": ["Si el cliente busca…", "Ir a"], "rows": [["Algo filoso y mineral para todo el omakase", "Marcoult, Larmandier-Bernier, Doyard, Gimonnet"], ["Más cuerpo y fruta (pinot noir / meunier)", "Gonet-Médeville, Roger Coulon, Wirth Michel, Egly-Ouriet"], ["Complejidad de crianza, notas de fruto seco", "Llopart, Huré Mémoire, Charles Heidsieck, Krug"], ["Mínima intervención", "Marguet (Shaman, Sapience), Bufadors"], ["Algo que no sea Champagne", "Recaredo, Llopart, Bufadors"], ["Una gran botella", "Lenoble Les Aventures, Marguet Sapience, Krug"]]}]'::jsonb),
  ('intro-blanco', 'blanco', 'Vinos blancos', 6, '[{"t": "p", "x": "Veinticuatro referencias en el orden de la carta. Solo el Ekam se sirve por copa."}, {"t": "p", "x": "**Mapa rápido para recomendar**"}, {"t": "table", "head": ["Si el cliente busca…", "Ir a"], "rows": [["Fresco, ácido, sin madera", "Ekam, Petit Chablis, Arinto dos Açores, Aligoté de Réno, Nozay"], ["Riesling", "Ekam (ligero), FIO (seco, complejo), Kreydenweiss (seco, con cuerpo), Schaefer (con dulzor)"], ["Chardonnay clásico de Borgoña", "Malandes, Rijckaert, Carillon, Boyer de Bar, Drouhin"], ["Algo distinto", "Fino Viña Corrales, Les Terrasses (Jura), Selma de Nin, Deiss"], ["Mínima intervención", "Selma de Nin, Cossard (Bigotes, Folatières), Chapuis Corton-Charlemagne"], ["España en grande", "Godello de Consuelo, El Sauco, Parcela en Aios"]]}]'::jsonb),
  ('intro-tinto', 'tinto', 'Vinos tintos', 7, '[{"t": "p", "x": "Veintiún referencias en el orden de la carta. Dos se sirven por copa. La carta no tiene rosados tranquilos; el único rosado es el Marguet Shaman, en espumosos."}, {"t": "p", "x": "Criterio general: en una barra de sushi el tinto es la excepción, así que la mayoría son tintos ligeros, de poco tanino. Las grandes botellas de Rioja, Ribera o Barolo están para el cliente que las pide a conciencia; conviene orientarlo hacia el tramo final del menú o servirlas después."}, {"t": "p", "x": "**Mapa rápido para recomendar**"}, {"t": "table", "head": ["Si el cliente busca…", "Ir a"], "rows": [["Tinto ligero que acompañe el menú", "Chapuis Côte d''Or, Saint-Cyr, Trousseau y Pinot Noir de Renardière, Lalama"], ["Pinot noir de Borgoña", "Chapuis, Duband, Cossard, Drouhin"], ["España fresca", "12 Volts, Lalama, Lo Noir, La Robina, Bruma de Arenero"], ["Nebbiolo", "Sandrone Valmaggiore (ligero), Barolo Le Vigne (serio)"], ["Mínima intervención", "Chapuis, Saint-Cyr, Renardière, Cossard"], ["Un clásico español de guarda", "904, 890, Peñas Aladas, Contador"]]}]'::jsonb),
  ('intro-whisky', 'whisky', 'Whisky japonés: lo mínimo que hay que saber', 8, '[{"t": "ul", "items": ["**Single malt**: whisky de cebada malteada hecho en una sola destilería, en alambique de cobre (*pot still*).", "**Blended**: mezcla de whiskies de malta con whiskies de grano (más ligeros). Hibiki es el ejemplo de la carta.", "**Turba (peat)**: si la malta se seca con humo de turba, el whisky sale ahumado. \"Peated\" y \"Smoky\" en la etiqueta avisan de eso.", "**\"Japanese Whisky\"**: desde 2021 la asociación de productores japoneses exige, para usar ese nombre, que el whisky se fermente, destile y envejezca al menos tres años en Japón, con agua japonesa. Todas las referencias de la carta son de destilerías que destilan allí.", "**New Born**: destilado joven, con menos de tres años de barrica. Legalmente aún no es whisky; las destilerías nuevas lo sacan para mostrar hacia dónde van.", "**Graduación**: los embotellados a 43 % son los clásicos; los de 55 % o más están a fuerza de barrica o cerca, y agradecen unas gotas de agua.", "**Madera**: bourbon (vainilla, coco), jerez o roble español (fruta seca, especia), *mizunara* o roble japonés (incienso, sándalo), vino tinto (fruta roja)."]}, {"t": "p", "x": "*Servicio (propuesta, a ajustar por Manu):* solo, en copa tipo tulipa, con agua aparte. Estos whiskies no son para highball."}]'::jsonb),
  ('pendientes-de-confirmar', 'general', 'Pendientes de confirmar', 9, '[{"t": "p", "x": "Datos que en esta guía quedaron marcados *a confirmar* y conviene cerrar con la botella o el distribuidor:"}, {"t": "ul", "items": ["Gassan: ficha sin revisar (se dejó como estaba).", "Nabeshima Junmai Daiginjo \"+\" (20 / 39 € en carta): falta saber qué cuvée es para hacerle ficha.", "Roger Coulon Heri Hodie: composición de la tirada actual.", "Lenoble Dosage Zéro V19 y Jacquesson 749: cosecha base.", "Marguet Sapience 2018: composición.", "Marcel Deiss Schlossberg 2021: nivel de dulzor.", "Drouhin Hospices de Beaune Meursault 1er Cru 2016 y Drouhin Vosne-Romanée 1er Cru 2019: cuvée y climat.", "Eulogio Pomares Parcela en Aios, Cantariña Godello de Consuelo: datos de elaboración.", "Josep Foraster La Robina y Bruma de Arenero: variedad y elaboración.", "La Rioja Alta 890 Selección Especial: añada.", "Yamazaki Umeshu Barrel-Aged: si es umeshu o whisky.", "Kuju New Born Peated #3 y Shizuoka Pot Still K: graduación y edición.", "OSO Citrus: estilo. Heiwa Yuzu Spritz: receta de la casa."]}]'::jsonb)
insert into public.guia_glosario (area, termino, definicion, orden) values
  ('Sake', 'Seimaibuai', 'Porcentaje del grano de arroz que queda tras el pulido. 60 % = se eliminó el 40 %.', 1),
  ('Sake', 'Junmai', 'Sake hecho solo con arroz, agua, koji y levadura, sin alcohol añadido.', 2),
  ('Sake', 'Ginjo / Daiginjo', 'Categorías por pulido (60 % o menos / 50 % o menos) y fermentación fría; perfil más aromático.', 3),
  ('Sake', 'Koji', 'Arroz inoculado con el hongo que convierte el almidón en azúcar. Amarillo en sake; el blanco (de shochu) aporta acidez cítrica.', 4),
  ('Sake', 'Shubo / moto', 'Pie de cuba: el cultivo inicial de levadura.', 5),
  ('Sake', 'Sokujo', 'Pie de cuba moderno, con ácido láctico añadido.', 6),
  ('Sake', 'Kimoto / Yamahai', 'Pies de cuba tradicionales, con fermentación láctica natural; dan más acidez y umami.', 7),
  ('Sake', 'Bodaimoto', 'Método medieval de pie de cuba, origen en los templos de Nara.', 8),
  ('Sake', 'Nama', 'Sake sin pasteurizar. Siempre en frío.', 9),
  ('Sake', 'Genshu', 'Sin diluir con agua tras el prensado; más alcohol.', 10),
  ('Sake', 'Muroka', 'Sin filtrar con carbón.', 11),
  ('Sake', 'Koshu', 'Sake añejo.', 12),
  ('Sake', 'Kijoshu', 'Sake elaborado sustituyendo parte del agua por sake; dulce y denso.', 13),
  ('Sake', 'Nihonshudo (SMV)', 'Escala de densidad: valores negativos, más dulce; positivos, más seco.', 14),
  ('Espumosos', 'Método tradicional', 'Segunda fermentación dentro de la botella.', 15),
  ('Espumosos', 'Lías', 'Levaduras muertas que quedan en la botella y dan complejidad.', 16),
  ('Espumosos', 'Degüelle', 'Expulsión de las lías antes del taponado final.', 17),
  ('Espumosos', 'Dosage', 'Azúcar que se añade tras el degüelle. Brut nature: nada; extra brut: hasta 6 g/L; brut: hasta 12 g/L.', 18),
  ('Espumosos', 'Blanc de blancs / de noirs', 'Blanco de uva blanca / blanco de uva tinta.', 19),
  ('Espumosos', 'NV', 'Sin añada: mezcla de varias cosechas.', 20),
  ('Espumosos', 'Millésimé', 'De una sola cosecha.', 21),
  ('Espumosos', 'Reserva perpetua / solera', 'Depósito que se rellena cada año sin vaciarse nunca.', 22),
  ('Espumosos', 'RM / NM', 'Viticultor que elabora su uva / casa que también compra uva.', 23),
  ('Espumosos', 'Special Club', 'Cuvée de prestigio de una asociación de viticultores de Champagne.', 24),
  ('Espumosos', 'Corpinnat', 'Marca colectiva de espumosos del Penedès, ecológicos y de larga crianza.', 25),
  ('Vino', 'Village / 1er cru / grand cru', 'Los tres escalones superiores de Borgoña, de pueblo a viñedo excepcional.', 26),
  ('Vino', 'Climat / lieu-dit', 'Parcela con nombre propio.', 27),
  ('Vino', 'Kimmeridgiano', 'Suelo de marga con fósiles marinos; Chablis y sur de Champagne.', 28),
  ('Vino', 'Ouillé', 'Barrica mantenida llena; sin oxidación. Lo contrario de la crianza bajo velo.', 29),
  ('Vino', 'Velo de flor', 'Capa de levaduras que protege al fino en la bota.', 30),
  ('Vino', 'Albariza', 'Suelo blanco calcáreo de Jerez.', 31),
  ('Vino', 'Saca', 'Extracción de vino de la solera para embotellar.', 32),
  ('Vino', 'Kabinett', 'Categoría alemana de madurez ligera; suele llevar azúcar residual.', 33),
  ('Vino', 'Complantation', 'Variedades distintas plantadas y vendimiadas juntas.', 34),
  ('Vino', 'Racimo entero', 'Fermentar con el raspón; da perfume y frescura.', 35),
  ('Vino', 'Qvevri', 'Tinaja de barro georgiana.', 36),
  ('Vino', 'Fudre', 'Tonel grande de madera; aporta poca madera al vino.', 37),
  ('Vino', 'Biodinámica', 'Agricultura ecológica que sigue además un calendario y preparados propios.', 38),
  ('Vino', 'Reducción', 'Olor a cerilla o fósforo al abrir; se va con aire.', 39),
  ('Vino', 'Tanino', 'Sensación secante de pieles, pepitas y madera.', 40),
  ('Destilados y otros', 'Single malt', 'Whisky de malta de una sola destilería.', 41),
  ('Destilados y otros', 'Blended', 'Mezcla de whiskies de malta y de grano.', 42),
  ('Destilados y otros', 'Peated', 'Elaborado con malta ahumada con turba.', 43),
  ('Destilados y otros', 'New Born', 'Destilado con menos de tres años; aún no es whisky.', 44),
  ('Destilados y otros', 'Mizunara', 'Roble japonés; da notas de incienso y sándalo.', 45),
  ('Destilados y otros', 'Umeshu', 'Licor de ume macerado con azúcar.', 46),
  ('Destilados y otros', 'Yuzushu', 'Licor de yuzu, aquí con base de sake.', 47)
insert into public.guia_preguntas (area, pregunta, orden) values
  ('Sake', '¿Qué indica un seimaibuai de 50 %?', 1),
  ('Sake', '¿Qué diferencia a un junmai de un sake que no lo es?', 2),
  ('Sake', '¿Por qué un yamahai o un kimoto tiene más acidez y umami que un sokujo?', 3),
  ('Sake', '¿Qué tiene de particular el koji del Natsu no Omoide y cómo se nota en la copa?', 4),
  ('Sake', '¿Qué cuidado exige un nama? ¿Cuáles de la barra lo son?', 5),
  ('Sake', 'El Biden ya no es de una sola añada. ¿Cómo se le explica al cliente?', 6),
  ('Sake', 'Un cliente pide "algo seco y limpio". ¿Qué dos sakes le proponés y por qué?', 7),
  ('Sake', 'Un cliente pide "algo raro". ¿A qué perfil vas?', 8),
  ('Espumosos', 'Explicá en tres frases cómo se hace un champagne.', 9),
  ('Espumosos', '¿Qué diferencia hay entre brut nature, extra brut y brut?', 10),
  ('Espumosos', '¿Qué es un blanc de noirs? Nombrá dos de la carta.', 11),
  ('Espumosos', '¿Qué tienen en común Heri Hodie y Mémoire?', 12),
  ('Espumosos', '¿Qué es Corpinnat y qué tres productores tenemos?', 13),
  ('Espumosos', '¿Qué significa el número en Jacquesson 749 y en Krug 174ème?', 14),
  ('Espumosos', '¿Cuáles son los espumosos de mínima intervención?', 15),
  ('Espumosos', '¿Por qué Vouette et Sorbée, siendo de Champagne, comparte suelo con Chablis?', 16),
  ('Blancos', 'Ordená de menor a mayor: Chablis 1er Cru, Petit Chablis, Chablis Grand Cru. ¿Qué referencia tenemos de cada uno?', 17),
  ('Blancos', '¿En qué se diferencian un Meursault y un Puligny-Montrachet?', 18),
  ('Blancos', '¿Qué quiere decir que Les Terrasses es un savagnin *ouillé*?', 19),
